/* eslint-disable prettier/prettier */
import { LitElement, html, TemplateResult } from 'lit';
import { customElement, query, property } from 'lit/decorators.js';

import '@awesome.me/webawesome/dist/components/callout/callout.js';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/input/input.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import '@awesome.me/webawesome/dist/components/icon/icon.js';

@customElement('lexml-ui-alterar-largura-imagem-modal')
export class AlterarLarguraImagemModalComponent extends LitElement {
  @query('wa-dialog') private dialog!: any;

  @property({ type: Boolean }) private exibirAviso = false;

  @property({ type: String }) private valorLargura = '';

  @property({ type: String }) private tipo = '';

  @property({ type: Function }) callback: any;

  private img: any;

  private openDialog() {
    if (this.dialog?.show) this.dialog.show();
    else if ('open' in this.dialog) this.dialog.open = true;
    else this.dialog?.setAttribute?.('open', '');
  }

  private closeDialog() {
    if (this.dialog?.hide) this.dialog.hide();
    else if (this.dialog?.close) this.dialog.close();
    else if ('open' in this.dialog) this.dialog.open = false;
    else this.dialog?.removeAttribute?.('open');
  }

  public show(img: any, width: string): void {
    this.img = img;
    this.valorLargura = width ? width.replace('%', '') : '';
    this.exibirAviso = false;
    this.openDialog();
  }

  public hide(): void {
    this.closeDialog();
  }

  private onAfterShow = () => {
    this.shadowRoot?.querySelector('wa-input')?.focus();
  };

  private onAfterHide = () => {
    this.exibirAviso = false;
    this.valorLargura = '';
    this.img = undefined;
  };

  private onInput = (e: Event) => {
    const target = e.target as HTMLInputElement;
    this.valorLargura = target.value ?? '';
    if (this.exibirAviso) this.exibirAviso = false;
  };

  private onKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Enter') this.alterarLargura();
  };

  private alterarLargura(): void {
    const width = parseInt(this.valorLargura, 10);
    if (isNaN(width) || width < 1 || width > 100) {
      this.exibirAviso = true;
      return;
    }
    this.callback?.(this.img, width);
    this.hide();
  }

  render(): TemplateResult {
    return html`
      <style>
        :host {
          font-family: var(--wa-font-sans);
        }
        .input-wrap {
          position: relative;
          display: inline-block;
        }

        .input-wrap wa-input::part(base) {
          width: 150px;
          padding-right: 1.75rem;
        }

        .input-wrap .suffix {
          position: absolute;
          right: 0.5rem;
          top: 50%;
          transform: translateY(-50%);
          color: var(--wa-color-neutral-500);
          font-weight: 500;
          pointer-events: none;
        }

        .input-wrap wa-input::part(base)::-webkit-outer-spin-button,
        .input-wrap wa-input::part(base)::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
        .input-wrap wa-input::part(base)[type='number'] {
          -moz-appearance: textfield;
        }
        .input-wrap {
          position: relative;
          display: inline-block;
        }
        wa-callout {
          margin-top: 20px;
        }
      </style>

      <wa-dialog
        label="Alterar a largura da Imagem"
        @wa-after-show=${this.onAfterShow}
        @wa-after-hide=${this.onAfterHide}
      >
        <label>Informe o percentual da largura da Imagem</label>

        <div class="input-wrap">
          <wa-input
            type="number"
            .value=${this.valorLargura}
            @input=${this.onInput}
          ></wa-input>
          <span class="suffix">%</span>
        </div>

        ${this.exibirAviso
          ? html`
              <wa-callout variant="warning" closable>
                <wa-icon slot="icon" name="exclamation-triangle"></wa-icon>
                Informe um valor numérico de 1 a 100.
              </wa-callout>
            `
          : null}

        <wa-button slot="footer" variant="brand" @click=${this.alterarLargura}>
          Alterar
        </wa-button>
        <wa-button slot="footer" @click=${this.hide}> Fechar </wa-button>
      </wa-dialog>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'lexml-ui-alterar-largura-imagem-modal': AlterarLarguraImagemModalComponent;
  }
}
