import { LitElement, html, css, TemplateResult } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { NotaRodape } from './notaRodape';

@customElement('panel-nota-rodape')
export class PanelNotaRodapeComponent extends LitElement {
  @property({ type: String }) posicao: 'lado' | 'abaixo' = 'abaixo';
  @property({ type: Boolean }) desabilitarTrocaOrientacao = false;

  private mudarPosicao(): void {
    if (this.desabilitarTrocaOrientacao) return;
    const nova = this.posicao === 'lado' ? 'abaixo' : 'lado';
    this.dispatchEvent(
      new CustomEvent('nota-rodape:mudar-posicao', {
        bubbles: true,
        composed: true,
        detail: { posicao: nova },
      }),
    );
  }
  static styles? = css`
    .notas-rodape {
      font-family: var(--eta-font-serif);
      display: flex;
      flex-direction: column;
      width: 100%;
      min-width: 0;
      height: 100%;
      min-height: 0;
      box-sizing: border-box;
      border: 1px solid #ccc;
      padding: 0 10px 10px 10px;
    }
    .notas-rodape h4 {
      font-family: var(--eta-font-sans);
      font-style: normal;
      font-size: 0.95rem;
      padding: 1rem 0px 0.5rem;
      margin: 0px;
    }
    .header-notas-rodape {
      border-bottom: var(--wa-color-gray-50) 0.5px solid;
      margin-bottom: 8px;
      height: 40px;
      padding: 0 2px;
      flex: 0 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      position: sticky;
      top: 0;
      background: white;
    }
    .header-notas-rodape wa-button::part(base) {
      height: 28px;
      width: 28px;
    }
    .notas-texto-vazio {
      padding-left: 20px;
      color: var(--wa-color-gray-50);
      font-style: italic;
    }

    .notas-scroll {
      flex: 1 1 auto;
      min-height: 0;
      overflow: auto;
    }

    .notas-rodape ol {
      padding-left: 20px;
      list-style: none;
      counter-reset: item;
      margin: 0px;
    }

    .notas-rodape li {
      padding: 0px;
      position: relative;
      cursor: pointer;
      display: flex;
      flex-direction: row;
      align-items: center;
      justify-content: space-between;
    }

    .notas-rodape li:hover {
      background-color: var(--wa-color-gray-95);
    }

    .notas-rodape li::before {
      content: counter(item);
      counter-increment: item;
      width: 20px;
      left: -20px;
      top: 4px;
      font-size: smaller;
      vertical-align: super;
      font-weight: bold;
      font-size: 12px;
      color: var(--wa-color-gray-50);
      text-align: right;
    }

    .notas-texto {
      flex-grow: 1;
      cursor: pointer;
      padding: 5px;
      color: var(--wa-color-gray-50);
    }

    .notas-texto p {
      margin-block-start: 0;
      margin-block-end: 0;
    }

    .notas-acoes {
      display: flex;
      flex-direction: row;
      align-items: center;
    }

    .notas-acao {
      margin-left: 5px;
      visibility: hidden;
      cursor: pointer;
    }

    .notas-rodape li:hover .notas-acao {
      visibility: visible;
    }

    .notas-checkbox {
      appearance: none;
      background: transparent;
      display: none;
    }

    .notas-checkbox:checked + .notas-texto {
      color: black;
      font-style: italic;
    }
  `;

  @property({ type: Array })
  notasRodape: NotaRodape[] = [];

  render(): TemplateResult {
    const podeTrocar = !this.desabilitarTrocaOrientacao;
    const indoPara =
      this.posicao === 'lado'
        ? 'Notas de rodapé para baixo'
        : 'Notas de rodapé para o lado';
    const icon =
      this.posicao === 'lado'
        ? 'layout-sidebar-reverse-vertical'
        : 'layout-sidebar-reverse';

    return html`
      <div class="notas-rodape">
        <div class="header-notas-rodape">
          <h4>Notas de rodapé</h4>
          ${podeTrocar
            ? html`
                <wa-button
                  title=${indoPara}
                  appearance="outlined"
                  pill
                  size="small"
                  @click=${this.mudarPosicao}
                >
                  <wa-icon
                    library="icons-ui-commons"
                    name=${icon}
                    variant="solid"
                    label=${indoPara}
                  ></wa-icon>
                </wa-button>
              `
            : null}
        </div>
        <div class="notas-scroll">${this.renderNotasRodape()}</div>
      </div>
    `;
  }

  renderNotasRodape(): TemplateResult {
    if (!this.notasRodape.length) {
      return html`
        <span class="notas-texto-vazio">
          Não há notas de rodapé registradas.
        </span>
      `;
    }

    const minNumero = Math.min(...this.notasRodape.map(n => n.numero));
    const startOffset = minNumero - 1;

    return html`
      <ol style="counter-reset: item ${startOffset};">
        ${this.notasRodape.map(
          (nr: NotaRodape) => html`
            <li>
              <input
                type="checkbox"
                idNotaRodape="${nr.id}"
                class="notas-checkbox"
                id="checkbox-${nr.id}"
                @change=${(): any => this.selecionarNotaRodape(nr.id)}
              />
              <label for="checkbox-${nr.id}" class="notas-texto"
                >${unsafeHTML(nr.texto)}</label
              >
              <span class="notas-acoes">
                <wa-button
                  class="notas-acao"
                  appearance="outlined"
                  variant="neutral"
                  size="small"
                  aria-label="Editar nota de rodapé"
                  title="Editar nota de rodapé"
                  idNotaRodape="${nr.id}"
                  @click=${(): any => this.editarNotaRodape(nr.id)}
                >
                  <wa-icon name="pen-to-square"></wa-icon>
                </wa-button>
                <wa-button
                  class="notas-acao"
                  appearance="outlined"
                  variant="neutral"
                  size="small"
                  aria-label="Excluir nota de rodapé"
                  title="Excluir nota de rodapé"
                  idNotaRodape="${nr.id}"
                  @click=${(): any => this.removerNotaRodape(nr.id)}
                >
                  <wa-icon name="trash"></wa-icon>
                </wa-button>
              </span>
            </li>
          `,
        )}
      </ol>
    `;
  }

  selecionarNotaRodape(idNotaRodape: any): void {
    const checkbox = this.shadowRoot?.querySelector(
      `#checkbox-${idNotaRodape}`,
    ) as HTMLInputElement | null;
    if (checkbox) {
      if (checkbox.checked) {
        const checkboxes = this.shadowRoot?.querySelectorAll(
          '.notas-checkbox',
        ) as NodeListOf<HTMLInputElement>;
        checkboxes?.forEach(cb => {
          if (cb.id !== checkbox.id) {
            cb.checked = false;
          }
        });
        this.localizarNotaRodape(idNotaRodape);
      } else {
        this.removerPulsarNotaRodape(idNotaRodape);
      }
    }
  }

  removerPulsarNotaRodape(idNotaRodape: any): void {
    this.emitirEvento(NOTA_RODAPE_REMOVER_PULSAR, idNotaRodape);
  }

  editarNotaRodape(idNotaRodape: any): void {
    this.emitirEvento(NOTA_RODAPE_EDITAR, idNotaRodape);
  }

  removerNotaRodape(idNotaRodape: any): void {
    this.emitirEvento(NOTA_RODAPE_REMOVER, idNotaRodape);
  }

  localizarNotaRodape(idNotaRodape: any): void {
    this.emitirEvento(NOTA_RODAPE_LOCALIZAR, idNotaRodape);
  }

  private emitirEvento(nomeEvento: string, idNotaRodape: any): void {
    this.dispatchEvent(
      new CustomEvent(nomeEvento, {
        bubbles: true,
        detail: { idNotaRodape },
      }),
    );
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'panel-nota-rodape': PanelNotaRodapeComponent;
  }
}

export const NOTA_RODAPE_LOCALIZAR = 'nota-rodape:localizar';
export const NOTA_RODAPE_REMOVER_PULSAR = 'nota-rodape:remover-pulsar';
export const NOTA_RODAPE_REMOVER = 'nota-rodape:remover';
export const NOTA_RODAPE_EDITAR = 'nota-rodape:editar';
