import { cursorEstaSobreBlotDel } from './moduloRevisao';

const Clipboard = Quill.import('modules/clipboard');
const Delta = Quill.import('delta');

const DOM_KEY = '__ql-matcher';
function traverse(node: any, elementMatchers: any, textMatchers: any): any {
  // Post-order
  if (node.nodeType === node.TEXT_NODE) {
    return textMatchers.reduce(function (delta: any, matcher: any) {
      return matcher(node, delta);
    }, new Delta());
  } else if (node.nodeType === node.ELEMENT_NODE) {
    return [].reduce.call(
      node.childNodes || [],
      (delta: any, childNode: any) => {
        let childrenDelta = traverse(childNode, elementMatchers, textMatchers);
        if (childNode.nodeType === node.ELEMENT_NODE) {
          childrenDelta = elementMatchers.reduce(function (
            childrenDelta: any,
            matcher: any,
          ) {
            return matcher(childNode, childrenDelta);
          }, childrenDelta);
          childrenDelta = (childNode[DOM_KEY] || []).reduce(function (
            childrenDelta: any,
            matcher: any,
          ) {
            return matcher(childNode, childrenDelta);
          }, childrenDelta);
        }
        return delta.concat(childrenDelta);
      },
      new Delta(),
    );
  } else {
    return new Delta();
  }
}

function deltaEndsWith(delta: any, text: any): any {
  let endText = '';
  for (
    let i = delta.ops.length - 1;
    i >= 0 && endText.length < text.length;
    --i
  ) {
    const op = delta.ops[i];
    if (typeof op.insert !== 'string') break;
    endText = op.insert + endText;
  }
  return endText.slice(-1 * text.length) === text;
}

export class ModuloCustomClipboard extends Clipboard {
  constructor(quill: any, options: any) {
    super(quill, options);
    this.quill.root.addEventListener('cut', this.onCut.bind(this));
  }

  onCut(e: any): any {
    if (this.quill?.revisao?.emRevisao) {
      e.preventDefault();
      e.stopPropagation();

      const range = this.quill.getSelection();
      if (range?.length) {
        this.copiarSelecaoParaClipboard();
        this.quill?.revisao?.handleRemove(range, null, null);
      }
    }
  }

  onPaste(e: any): any {
    if (cursorEstaSobreBlotDel(this.quill)) {
      e.preventDefault();
      e.stopPropagation();
    }
    // super.onPaste(e);

    if (e.defaultPrevented || !this.quill.isEnabled()) return;
    const range = this.quill.getSelection();
    let delta = new Delta().retain(range.index);
    const scrollTop = this.quill.scrollingContainer.scrollTop;
    this.container.focus();
    this.quill.selection.update('silent');
    setTimeout(() => {
      delta = delta.concat(this.convert()).delete(range.length);

      // WORKAROUND: o Quill insere um \t (tab) quando cola conteúdo rich text que possui formatação de correção ortográfica
      // TODO: descobrir por quê e tentar corrigir na fonte
      delta.ops = delta.ops.filter(
        (o: any) => o.insert !== '\t' || o.attributes,
      );

      this.quill.updateContents(delta, 'user');
      // range.length contributes to delta.length()
      this.quill.setSelection(delta.length() - range.length, 'silent');
      this.quill.scrollingContainer.scrollTop = scrollTop;
      this.quill.focus();
    }, 1);
  }

  convert(html?: string): any {
    if (typeof html === 'string') {
      // this.container.innerHTML = html.replace(/\>\r?\n +\</g, '><'); // Remove spaces between tags
      this.container.innerHTML = html.replace(/>\r?\n +</g, '><'); // Remove spaces between tags
      return this.convert();
    }
    const formats = this.quill.getFormat(this.quill.selection.savedRange.index);
    if (formats['code']) {
      const text = this.container.innerText;
      this.container.innerHTML = '';
      return new Delta().insert(text, { ['code']: formats['code'] });
    }
    const [elementMatchers, textMatchers] = this.prepareMatching();
    let delta = traverse(this.container, elementMatchers, textMatchers);
    // Remove trailing newline
    if (
      deltaEndsWith(delta, '\n') &&
      delta.ops[delta.ops.length - 1].attributes === null
    ) {
      delta = delta.compose(new Delta().retain(delta.length() - 1).delete(1));
    }
    // debug.log('convert', this.container.innerHTML, delta);
    this.container.innerHTML = '';
    return delta;
  }

  copiarSelecaoParaClipboard(): any {
    const selection = window.getSelection();

    if (selection) {
      if (navigator.clipboard) {
        // Cria um elemento div temporário para armazenar a seleção
        const tempElement = document.createElement('div');

        // Clona a seleção e a insere no elemento div temporário
        for (let i = 0; i < selection.rangeCount; i++) {
          tempElement.appendChild(selection.getRangeAt(i).cloneContents());
        }

        // Copia o conteúdo do elemento div temporário para a área de transferência
        navigator.clipboard
          .write([
            new ClipboardItem({
              'text/plain': new Blob([tempElement.innerText], {
                type: 'text/plain',
              }),
              'text/html': new Blob([tempElement.outerHTML], {
                type: 'text/html',
              }),
            }),
          ])
          .finally(() => tempElement.remove());
      } else {
        console.log('Clipboard API não suportada');
        document.execCommand('copy'); // Alternativa para o caso de não suportar a Clipboard API
      }
    }
  }
}
